      "nav.about": "About",
      "ab.eyebrow": "About OmniFabric",
      "ab.title": "Enterprise data intelligence for the sovereign cloud",
      "ab.desc": "OmniFabric is an enterprise-grade data intelligence platform — the Snowflake or Databricks of the sovereign cloud. It combines CloudSigma's sovereign cloud with MatrixOrigin's AI-native data platform, so AI runs on trusted data without ever leaving your jurisdiction.",
      "ab.mission.eyebrow": "Our mission",
      "ab.mission.title": "Make trusted AI the default — on infrastructure you control",
      "ab.mission.p": "Every organization should be able to run production AI on data it owns, with decisions it can audit. OmniFabric unifies all your enterprise data, knowledge and intelligence on infrastructure you fully control — from AI hype to AI ROI.",
      "ab.cs.tag": "Cloud heritage",
      "ab.cs.name": "CloudSigma",
      "ab.cs.title": "Sovereign, flexible cloud infrastructure",
      "ab.cs.p1": "Founded in 2009 in Zürich, Switzerland by Robert Jenkin and Patrick Baillie, CloudSigma pioneered a pure IaaS where customers define their own infrastructure with no artificial restrictions.",
      "ab.cs.p2": "Operating from Zurich, Las Vegas and Washington and serving more than 75,000 customers, CloudSigma delivers secure, sustainable and sovereign Cloud-as-a-Service — and now Intelligence-as-a-Service.",
      "ab.cs.f1l": "Founded",
      "ab.cs.f1v": "2009",
      "ab.cs.f2l": "Headquarters",
      "ab.cs.f2v": "Zürich, Switzerland",
      "ab.cs.f3l": "Customers",
      "ab.cs.f3v": "75,000+",
      "ab.cs.f4l": "Footprint",
      "ab.cs.f4v": "Zurich · Las Vegas · Washington",
      "ab.cs.link": "Visit cloudsigma.com",
      "ab.mo.tag": "Data &amp; AI heritage",
      "ab.mo.name": "MatrixOrigin",
      "ab.mo.title": "An AI-native data intelligence platform",
      "ab.mo.p1": "Founded in 2021 and backed by 5Y Capital and K2VC, MatrixOrigin builds MatrixOne — an open-source, AI-native, MySQL-compatible HTAP database with Git-for-Data version control and built-in vector and full-text search.",
      "ab.mo.p2": "MatrixOne 1.0 went GA in 2023, MatrixOne Intelligence launched in 2024, and in 2025 the company expanded globally with CloudSigma — with offices in the US, Shanghai, Shenzhen and Beijing.",
      "ab.mo.f1l": "Founded",
      "ab.mo.f1v": "2021",
      "ab.mo.f2l": "Offices",
      "ab.mo.f2v": "US · Shanghai · Shenzhen · Beijing",
      "ab.mo.f3l": "Funding",
      "ab.mo.f3v": "$50M+ · 5Y Capital, K2VC",
      "ab.mo.f4l": "Engine",
      "ab.mo.f4v": "Hyper-converged HTAP · Git-for-Data",
      "ab.mo.link": "Visit matrixorigin.io",
      "ab.together.eyebrow": "Why it matters",
      "ab.together.title": "Two foundations, one fabric",
      "ab.together.p": "OmniFabric pairs CloudSigma's sovereign, flexible cloud with MatrixOrigin's AI-native data platform — giving you all-in-one data and AI on infrastructure you control.",
      "ab.tg1.t": "Sovereign by design",
      "ab.tg1.d": "Run in your cloud, on-prem, or air-gapped — your data stays in your region, under your control.",
      "ab.tg2.t": "All-in-one",
      "ab.tg2.d": "Data, vectors, models and agents in one platform, not a stack of services to stitch together.",
      "ab.tg3.t": "Open &amp; flexible",
      "ab.tg3.d": "MySQL-compatible, SQL and open APIs — define your infrastructure your way, with no lock-in.",
      "ab.cta.title": "See what one fabric can do",
      "ab.cta.desc": "Explore the platform, or talk to our team about bringing sovereign data and AI together.",
