      "rl.four.h": "四大数据现实阻碍 AI 规模化落地生产",
      "rl.d1.t": "数据孤岛",
      "rl.d1.d": "企业并行运行 10–50+ 个智能体。在割裂系统之间搬运数据是首要瓶颈——上下文断裂会产生糟糕的 AI 结果。",
      "rl.d2.t": "非结构化混乱",
      "rl.d2.d": "传统数据库看不到锁在文档、邮件和多媒体中的约 80% 业务知识。AI 原生平台必须把文档当作数据来处理。",
      "rl.d3.t": "脆弱的 ETL",
      "rl.d3.d": "把模型连到数据需要大量胶水代码，而它们经常出问题。每个新智能体都变成数月的工程项目，复杂度呈指数增长。",
      "rl.d4.t": "安全与信任",
      "rl.d4.d": "关键业务 AI 要求主权与治理：保护 PII、端到端可追溯、结果可复现——以及对错误决策的“撤销”能力。",
