      "s.cs1.tag": "交通",
      "s.cs1.t": "从数据混乱到业务洞察",
      "s.cs1.pr": "运营数据割裂在 OT 与 IT 系统之间——收费车道、车牌识别、RFID、支付网关、交通传感器——实时可见性有限，根因分析缓慢。",
      "s.cs1.so": "实时流式接入 Bronze · Silver · Gold 分层，知识库加语义层，以及支持自然语言问答的数据智能体——运行在主权 AI 基础设施与私有 LLM 之上。",
      "s.cs1.o": "洞察时间从数周或数月缩短到几分钟，TB 级分析秒级完成。",
      "s.cs2.tag": "电信",
      "s.cs2.t": "从信息到专业知识",
      "s.cs2.pr": "企业知识分散在 ERP、CRM、SharePoint、文档系统与协作工具中——未 AI 就绪、未治理，且依赖少数领域专家。",
      "s.cs2.so": "来自 S3、Google Drive 与用户上传的非结构化文档被解析、切分、向量化并索引到受治理的知识库中，回答附带来源引用。",
      "s.cs2.o": "查找信息与获取洞察提速 90% 以上——覆盖支持、运营、培训与销售。",
      "s.cs3.tag": "油气",
      "s.cs3.t": "从人才招聘到人才智能",
      "s.cs3.pr": "大批量招聘无法规模化：人工筛选简历、评估不一致，并担心把敏感 HR 数据交给外部 AI 服务商——SLA 为每月 50,000 份简历。",
      "s.cs3.so": "由支持阿拉伯语的主权 LLM 识别、解析并评分简历，分数写入结构化表，并为招聘人员提供简洁的前端与排序候选名单——订阅或按量付费。",
      "s.cs3.o": "每小时处理数千份简历——比人工筛选快数十倍。同样的模式适用于发票、合同与招标文件。",
      "s.ind7": "能源与公用事业",
