      "cc3.ch": "每次新品上市都需要 1–2 个月的反复沟通与集中培训，市场人员才能准备好推广。",
      "cc3.sol": "OmniFabric 将内部案例资料与产品文档统一为 AI 培训助手，市场人员可自助学习并自主训练如何推广新品。",
      "cc3.res": "培训效率提升 80%：员工自行上手新品，只需渠道经理轻量引导，无需数月的反复培训会议。",
      "cc4.ch": "每份平台标书需要 1–2 周的人工组装，手动汇集分散的资料和历史案例。",
      "cc4.sol": "OmniFabric 将内部投标资料与历史案例整合进投标智能体，自动起草标书。",
      "cc4.res": "标书制作从 1–2 周缩短到 1–2 天——提速约 10 倍。",
      "cc5.ch": "分析师大部分时间都花在跨 60 多个数据源收集资料,而非形成判断。",
      "cc5.sol": "Stone Castle 部署 OmniFabric,跨 60 多个数据源自动化投研,并实现实时组合监控。",
      "cc5.res": "约 80% 的分析师工时被释放用于策略,并可实时监控。",
      "cc6.ch": "理赔与保单的人工审查缓慢,在期限压力下风险条款容易被漏看。",
      "cc6.sol": "OmniFabric 上的文档智能将理赔与保单解析为可自动更新的知识库,并给出带引用、由 AI 识别的风险。",
      "cc6.res": "风险条款审查从 16 天缩短到约 1 分钟。",
