      "pillars.title": "一个平台 · 一份数据 · 一套技术栈",
      "pillars.desc": "云原生的统一 Data + AI 平台。企业 AI 的大脑、记忆与手脚——模型、数据与智能体——运行在同一个受治理的底座上，在自优化飞轮中相互增强。",
