      "pr.faq.title": "你的疑问,这里有答案",
      "pr.faq.q1": "我还需要单独的向量数据库吗?",
      "pr.faq.a1": "不需要。向量检索是 OmniFabric 的原生能力——嵌入就在关系数据旁边,你可以在一条语句里完成关键词 + 向量混合查询,无需额外系统去运维或付费。",
      "pr.faq.q2": "按用量计费是怎么算的?",
      "pr.faq.a2": "你只为实际消耗的存储、算力和模型调用付费。每一笔费用都对应可审计的用量记录,财务与工程都能清楚看到账单的来源。",
      "pr.faq.q3": "可以接入我自己的模型吗?",
      "pr.faq.a3": "可以。通过一个 API 调用任意托管 LLM 或嵌入模型,或接入你自己的私有端点。没有锁定——每次调用都纳入同样的血缘与治理。",
      "pr.faq.q4": "OmniFabric 支持私有化部署吗?",
      "pr.faq.a4": "企业版支持单租户云与完全私有化部署,提供多区域数据驻留、SSO 以及专属解决方案架构师。",
      "pr.faq.q5": "回滚后智能体的记忆会怎样?",
      "pr.faq.a5": "记忆是带版本且全程审计的。你可以查看任意时间点的记忆并安全回滚——每一次写入都可追溯、可逆。",
      "pr.cta.title": "准备把数据与 AI 编织到一起了吗?",
      "pr.cta.desc": "开通一个免费工作区,接入第一个数据源,今天就交付一个可信智能体。",
      "pr.cta.b1": "免费开始构建",
      "pr.cta.b2": "联系销售",

