      "s.cs.p": "Le problème, le pipeline sur OmniFabric et le résultat — chacun sur une infrastructure souveraine avec un LLM privé.",
      "s.cs.prl": "Problème",
      "s.cs.sol": "Sur OmniFabric",
      "s.cs.ol": "Résultat business",
      "s.cs1.tag": "Transport",
      "s.cs1.t": "Du chaos des données à l'insight business",
      "s.cs1.pr": "Données opérationnelles fragmentées entre systèmes OT et IT — voies de péage, ANPR, RFID, passerelles de paiement, capteurs de trafic — avec une visibilité temps réel limitée et une analyse des causes lente.",
      "s.cs1.so": "Streaming temps réel vers des couches Bronze · Silver · Gold, une base de connaissances plus une couche sémantique, et un agent de données pour les Q&amp;R en langage naturel — sur une infrastructure IA souveraine avec un LLM privé.",
      "s.cs1.o": "Délai d'obtention des insights : de semaines ou mois à quelques minutes, avec des analyses à l'échelle du To en secondes.",
      "s.cs2.tag": "Télécoms",
      "s.cs2.t": "De l'information à l'expertise",
      "s.cs2.pr": "Connaissances d'entreprise fragmentées entre ERP, CRM, SharePoint, systèmes documentaires et outils collaboratifs — ni prêtes pour l'IA, ni gouvernées, et dépendantes de quelques experts métier.",
      "s.cs2.so": "Documents non structurés issus de S3, Google Drive et d'imports, analysés, découpés, vectorisés et indexés dans une base de connaissances gouvernée, avec des réponses citant leurs sources.",
      "s.cs2.o": "Recherche d'information et insights 90 %+ plus rapides — support, opérations, formation et ventes.",
      "s.cs3.tag": "Pétrole &amp; gaz",
      "s.cs3.t": "Du recrutement à l'intelligence des talents",
      "s.cs3.pr": "Le recrutement à grand volume ne passait pas à l'échelle : tri manuel des CV, évaluations incohérentes et craintes d'envoyer des données RH sensibles à des fournisseurs d'IA externes — avec un SLA de 50 000 CV par mois.",
      "s.cs3.so": "CV reconnus, analysés et notés par des LLM souverains avec prise en charge de l'arabe, scores écrits dans des tables structurées, et une interface recruteur simple pour des shortlists classées — abonnement ou paiement à l'usage.",
      "s.cs3.o": "Des milliers de CV par heure — des dizaines de fois plus vite que le tri manuel. Le même schéma s'applique aux factures, contrats et appels d'offres.",
      "s.ind7": "Énergie &amp; services publics",
