      "px.use.h": "Ne payez que ce que vous consommez",
      "px.use.p": "En plus du calcul, trois services mesurés — facturés purement à la consommation et détaillés sur la même facture.",
      "px.ai.t": "Services d'IA",
      "px.ai.p": "Accédez à plus de 100 modèles hébergés — chat, embeddings et rerankers — via une seule API. Facturé au million de tokens ; utilisez vos propres clés fournisseur pour un report au coût.",
      "px.ai.in": "Tokens d'entrée",
