      "demo.cta.t": "Vous en voulez un sur vos données ?",
      "demo.cta.d": "Démarrez gratuitement et connectez votre première source en minutes, ou réservez une démo en direct avec notre équipe.",
      "sov.h.eb": "Souveraineté des données",
      "sov.h.h": "Vos données et votre IA ne quittent jamais votre contrôle",
      "sov.h.p": "Pour les charges réglementées et critiques, OmniFabric s'exécute là où vos données doivent résider — votre région, votre infrastructure, vos règles. Résidence complète, flexibilité de déploiement et gouvernance de bout en bout, intégrées.",
      "sov.h.c1t": "Résidence régionale des données",
      "sov.h.c1d": "Vos données et modèles restent dans la région par défaut, conformément aux exigences locales de résidence et de souveraineté.",
      "sov.h.c2t": "Déployez partout",
      "sov.h.c2d": "Exécutez sur cloud local, on-premise ou edge hybride — la même plateforme, là où la conformité l'exige.",
      "sov.h.c3t": "Gouvernance unifiée",
      "sov.h.c3d": "RBAC, pistes d'audit complètes et snapshots pour chaque résultat piloté par l'IA — pas de décisions boîte noire.",
      "sov.h.c4t": "Prêt pour la conformité",
      "sov.h.c4d": "Protégez les données personnelles, tracez chaque décision de bout en bout et reproduisez tout résultat pour validation juridique et réglementaire.",
      "sov.p.h": "Souverain par conception — déployez partout, gouvernez tout",
      "sov.p.p": "L'IA critique exige souveraineté et gouvernance stricte. OmniFabric garde vos données dans votre région et sur une infrastructure que vous contrôlez, avec une auditabilité complète de chaque appel de modèle et décision d'agent.",
      "sov.p.m1t": "Cloud local",
      "sov.p.m1d": "Déployez dans une région souveraine du cloud de votre choix — vos données ne franchissent jamais les frontières.",
      "sov.p.m2t": "On-premise",
      "sov.p.m2d": "Exécutez entièrement dans votre propre centre de données, totalement isolable pour les charges les plus sensibles.",
      "sov.p.m3t": "Edge hybride",
      "sov.p.m3d": "Gardez les données sensibles on-premise tout en débordant le calcul vers le cloud — une plateforme, un plan de contrôle.",
      "sov.p.g1": "Résidence des données en région",
      "sov.p.g2": "RBAC et isolation multi-tenant",
      "sov.p.g3": "Lignée et pistes d'audit complètes",
      "sov.p.g4": "Snapshots ponctuels et rejeu",
      "sov.p.g5": "Protection des PII et masquage des données",
      "sov.p.g6": "Sorties reproductibles et auditables",
      "cust.trusted": "Ils nous font confiance",
      "cc1.ch": "Les features et modèles IA étaient reconstruits en silos d'un service à l'autre, ralentissant chaque projet et gonflant les coûts de calcul.",
      "cc1.sol": "Tencent a bâti sur OmniFabric une plateforme de données multimodale et un système de gestion des features, où les équipes publient, découvrent et réutilisent les features depuis un magasin gouverné.",
      "cc1.res": "La réutilisation des features entre services a progressé de 40 % et les cycles de développement ont diminué de 30 %.",
      "cc2.ch": "Les données de transaction marchandes à fort volume étaient difficiles à analyser en temps réel.",
      "cc2.sol": "Olsera a diffusé les transactions dans OmniFabric pour une analytique en temps réel et des copilotes de support marchand instantanés.",
      "cc2.res": "Les marchands obtiennent des insights en temps réel et les copilotes répondent à partir de données en direct.",
      "cc3.ch": "Chaque lancement produit exigeait 1 à 2 mois de communications répétées et de sessions de formation collectives avant que le marketing soit prêt à le promouvoir.",
      "cc3.sol": "OmniFabric a unifié les cas internes et la documentation produit dans un assistant de formation IA, permettant aux équipes marketing d'apprendre et de s'entraîner seules à promouvoir les nouveautés.",
      "cc3.res": "Efficacité de formation +80 % : les équipes montent seules en compétence sur les nouveaux produits, avec un léger accompagnement des responsables de canal au lieu de mois de réunions répétées.",
      "cc4.ch": "Chaque dossier d'appel d'offres demandait 1 à 2 semaines d'assemblage manuel, en rassemblant à la main des documents dispersés et des cas passés.",
      "cc4.sol": "OmniFabric a intégré les documents d'appel d'offres internes et les cas historiques dans un agent de soumission qui rédige automatiquement les dossiers.",
      "cc4.res": "La création d'un dossier est passée de 1–2 semaines à 1–2 jours — environ 10× plus vite.",
      "cc5.ch": "Les analystes passaient l'essentiel de leur temps à collecter des données sur plus de 60 sources au lieu de se forger une opinion.",
      "cc5.sol": "Stone Castle a déployé OmniFabric pour automatiser la recherche sur plus de 60 sources avec un suivi de portefeuille en temps réel.",
      "cc5.res": "Environ 80 % du temps des analystes a été libéré pour la stratégie, avec un suivi en temps réel.",
      "cc6.ch": "La revue manuelle des sinistres et polices était lente, et les clauses à risque faciles à manquer.",
      "cc6.sol": "L'intelligence documentaire sur OmniFabric a transformé sinistres et polices en une base de connaissances auto-actualisée, avec des risques détectés par IA et sourcés.",
      "cc6.res": "La revue des clauses à risque est passée de 16 jours à environ une minute.",
      "s.hero.eb": "Solutions",
      "s.hero.h": "Transformez vos données d'entreprise en actifs prêts pour l'IA",
      "s.hero.p": "Chaque schéma à forte valeur est un pipeline gouverné sur OmniFabric — des données brutes au résultat en production. Des capacités données aux agents déployés, une seule plateforme alimente tout.",
