      "s.cap.p": "Cinq capacités clés qui transforment des données d'entreprise brutes et fragmentées en actifs fiables et prêts pour l'IA.",
      "s.c1.t": "Intelligence documentaire",
      "s.c1.d": "Libérez les données prisonnières de documents complexes. Automatisez tout le flux — analyse, extraction, génération — et créez un Document Copilot prêt pour la production.",
