      "p.hero.h": "Une plateforme Data + IA unifiée et cloud-native",
      "p.hero.p": "Quatre couches unifiées pour les charges IA, livrées en deux produits — OmniFabric One et OmniFabric GenAI Workspace — gouvernées de bout en bout. Vos données ne quittent jamais votre domaine.",
