      "p.eng.p": "Charges transactionnelles, analytiques, séries temporelles, vectorielles et plein texte dans une seule base compatible MySQL — avec stockage et calcul illimités et indépendamment évolutifs.",
      "p.eng1.s": "Moteur tout-en-un",
      "p.eng1.d": "Transactionnel, analytique, séries temporelles, vectoriel &amp; plein texte — dans une seule base. Simplifiez votre architecture de données.",
      "p.eng2.s": "Haute élasticité",
      "p.eng2.d": "Stockage et calcul illimités, évolutifs indépendamment.",
      "p.eng3.s": "Économique",
      "p.eng3.d": "Paiement à l'usage sur stockage partagé avec une source unique de données.",
      "p.eng4.s": "Compatible MySQL",
      "p.eng4.d": "Compatible protocole et SQL avec MySQL 8.0 — zéro migration, outils familiers.",
      "p.cm.eb": "OmniFabric GenAI Workspace",
      "p.cm.h": "Des données brutes aux agents IA",
      "p.cm.p": "Un pipeline gouverné qui transforme les sources structurées et non structurées en connaissances fiables et prêtes pour l'IA — puis les sert aux agents et à la recherche.",
      "p.cm1.t": "Sources de données",
      "p.cm1.f1": "<b>SQL &amp; stockage objet</b> — bases, lacs et fichiers, en historique et en incrémental.",
      "p.cm1.f2": "<b>Documents, médias &amp; SaaS</b> — PDF, images, audio, vidéo et applications métier.",
      "p.cm2.t": "Intégrer &amp; traiter",
      "p.cm2.f1": "<b>Nettoyage, découpage &amp; enrichissement</b> — opérateurs intégrés plus nœuds personnalisés, orchestrés visuellement.",
      "p.cm2.f2": "<b>Embedding &amp; versionnage des données</b> — chaque base de connaissances versionnée, reproductible et réversible.",
      "p.cm3.t": "Modèles &amp; gouvernance",
      "p.cm3.f1": "<b>Orchestration LLM, embedding, vision &amp; parole</b> — open source ou commerciaux, interchangeables.",
      "p.cm3.f2": "<b>RBAC &amp; confidentialité</b> — accès fin, protection des PII et traçabilité complète à chaque appel.",
      "p.cm4.t": "Servir",
      "p.cm4.f1": "<b>Agent de données &amp; Chat2BI</b> — questions en langage naturel sur toutes vos données, avec agrégation et exploration.",
      "p.cm4.f2": "<b>Recherche d'entreprise &amp; workflows agentiques</b> — réponses fondées avec citations, et agents qui agissent.",
      "p.sec.eb": "Niveau entreprise",
      "p.sec.h": "Sécurité et contrôle d'accès intégrés",
      "p.sec1.t": "Contrôle d'accès RBAC",
      "p.sec1.d": "Gestion fine des utilisateurs, rôles, permissions et accès aux données — jusqu'à la colonne.",
      "p.sec2.t": "Isolation multi-tenant",
      "p.sec2.d": "Des tenants isolés avec stockage et calcul dédiés, pour que les équipes et les données ne franchissent jamais les frontières.",
      "p.sec3.t": "Lignée et pistes d'audit",
      "p.sec3.d": "Chaque transformation et décision d'agent est traçable de bout en bout — prêt pour les audits GDPR, SOC 2 et vos propres politiques.",
      "p.dep.eb": "Déployez à votre façon",
      "p.dep.h": "Déploiement privé ou cloud managé",
      "p.dep1.t": "Déploiement privé",
      "p.dep1.f1": "Environnement privé isolé — données entièrement sous votre contrôle.",
      "p.dep1.f2": "Réseau privé haute performance — sans latence d'internet public.",
      "p.dep1.f3": "Déploiement unique, usage durable, coût prévisible.",
      "p.dep1.cta": "Nous contacter",
