      "nav.about": "À propos",
      "ab.eyebrow": "À propos d’OmniFabric",
      "ab.title": "L'intelligence des données d'entreprise pour le cloud souverain",
      "ab.desc": "OmniFabric est une plateforme d'intelligence des données de niveau entreprise — le Snowflake ou Databricks du cloud souverain. Elle associe le cloud souverain de CloudSigma à la plateforme de données IA-native de MatrixOrigin, pour que l'IA s'exécute sur des données fiables sans jamais quitter votre juridiction.",
      "ab.mission.eyebrow": "Notre mission",
      "ab.mission.title": "Faire de l’IA de confiance la norme — sur une infrastructure que vous maîtrisez",
      "ab.mission.p": "Chaque organisation devrait pouvoir exécuter une IA de production sur ses propres données, avec des décisions auditables. OmniFabric unifie toutes vos données, connaissances et intelligence d'entreprise sur une infrastructure que vous contrôlez entièrement — du battage IA au ROI de l'IA.",
      "ab.cs.tag": "Héritage cloud",
      "ab.cs.name": "CloudSigma",
      "ab.cs.title": "Une infrastructure cloud souveraine et flexible",
      "ab.cs.p1": "Fondée en 2009 à Zurich (Suisse) par Robert Jenkin et Patrick Baillie, CloudSigma a été pionnière d’un IaaS pur où les clients définissent leur propre infrastructure sans restrictions artificielles.",
      "ab.cs.p2": "Présente à Zurich, Las Vegas et Washington et servant plus de 75 000 clients, CloudSigma propose un Cloud-as-a-Service sûr, durable et souverain — et désormais un Intelligence-as-a-Service.",
      "ab.cs.f1l": "Fondée",
      "ab.cs.f1v": "2009",
      "ab.cs.f2l": "Siège",
      "ab.cs.f2v": "Zurich, Suisse",
      "ab.cs.f3l": "Clients",
      "ab.cs.f3v": "75 000+",
      "ab.cs.f4l": "Présence",
      "ab.cs.f4v": "Zurich · Las Vegas · Washington",
      "ab.cs.link": "Visiter cloudsigma.com",
      "ab.mo.tag": "Héritage data &amp; IA",
      "ab.mo.name": "MatrixOrigin",
      "ab.mo.title": "Une plateforme d’intelligence des données AI-native",
      "ab.mo.p1": "Fondée en 2021 et soutenue par 5Y Capital et K2VC, MatrixOrigin développe MatrixOne — une base HTAP open source, IA-native et compatible MySQL, avec versionnage Git-for-Data et recherche vectorielle et plein texte intégrée.",
      "ab.mo.p2": "MatrixOne 1.0 est passé en GA en 2023, MatrixOne Intelligence a été lancé en 2024, et en 2025 l'entreprise s'est déployée à l'international avec CloudSigma — avec des bureaux aux États-Unis, à Shanghai, Shenzhen et Pékin.",
      "ab.mo.f1l": "Fondée",
      "ab.mo.f1v": "2021",
      "ab.mo.f2l": "Bureaux",
      "ab.mo.f2v": "États-Unis · Shanghai · Shenzhen · Pékin",
      "ab.mo.f3l": "Financement",
      "ab.mo.f3v": "50 M$+ · 5Y Capital, K2VC",
      "ab.mo.f4l": "Moteur",
      "ab.mo.f4v": "HTAP hyperconvergé · Git-for-Data",
      "ab.mo.link": "Visiter matrixorigin.io",
      "ab.together.eyebrow": "Pourquoi c’est important",
      "ab.together.title": "Deux fondations, une seule trame",
      "ab.together.p": "OmniFabric associe le cloud souverain et flexible de CloudSigma à la plateforme de données AI-native de MatrixOrigin — pour une data et une IA tout-en-un sur une infrastructure que vous maîtrisez.",
      "ab.tg1.t": "Souverain par conception",
      "ab.tg1.d": "Exécutez dans votre cloud, sur site ou en environnement isolé — vos données restent dans votre région, sous votre contrôle.",
      "ab.tg2.t": "Tout-en-un",
      "ab.tg2.d": "Données, vecteurs, modèles et agents dans une seule plateforme, pas une pile de services à assembler.",
      "ab.tg3.t": "Ouvert &amp; flexible",
      "ab.tg3.d": "Compatible MySQL, SQL et API ouvertes — définissez votre infrastructure à votre façon, sans verrouillage.",
      "ab.cta.title": "Découvrez ce qu’une seule trame permet",
      "ab.cta.desc": "Explorez la plateforme, ou parlez à notre équipe pour réunir données souveraines et IA.",
