      "hero.badge.pill": "NOUVEAU",
      "hero.badge.text": "Le runtime d’agents et la mémoire longue durée sont désormais en disponibilité générale",
      "hero.title": "L'intelligence des données d'entreprise<br><span class=\"grad\">pour le cloud souverain.</span>",
      "hero.lead": "OmniFabric unifie toutes vos données, connaissances et intelligence d'entreprise sur une infrastructure que vous contrôlez entièrement — l'IA s'exécute sur des données fiables sans jamais quitter votre juridiction.",
      "hero.cta1": "Commencer gratuitement",
