      "cmp.r1.dw": "Producto unificado; OLTP añadido por adquisición, sin HTAP nativo",
      "cmp.r2.oss": "El más alto: construir &amp; operar todo",
      "cmp.r2.dw": "Moderado: sincronización multimotor, IA como complemento",
      "cmp.r3.oss": "Cualquier infraestructura, pero autooperada",
      "cmp.r3.dw": "Principalmente su nube gestionada",
      "cmp.r4.oss": "Integre los modelos usted mismo",
      "cmp.r4.dw": "Solo modelos cerrados",
      "cmp.r5.oss": "Software gratuito, alto coste operativo",
      "cmp.r5.dw": "Premium",
      "wf.eb": "Estrategia de IA empresarial",
      "wf.h": "De un agente a una fuerza laboral de agentes",
      "wf.p": "IA + marketing, I+D, datos, gestión del conocimiento, atención al cliente, RR. HH. e investigación, sobre una base que escala del primer agente a una fuerza laboral gobernada.",
