      "s.cs.eb": "Casos de estudio por sector",
      "s.cs.h": "Tres despliegues, un mismo patrón",
      "s.cs.p": "El problema, el pipeline en OmniFabric y el resultado, cada uno sobre infraestructura soberana con un LLM privado.",
      "s.cs.prl": "Problema",
      "s.cs.sol": "En OmniFabric",
      "s.cs.ol": "Resultado de negocio",
      "s.cs1.tag": "Transporte",
      "s.cs1.t": "Del caos de datos al insight de negocio",
      "s.cs1.pr": "Datos operativos fragmentados entre sistemas OT e IT (carriles de peaje, ANPR, RFID, pasarelas de pago, sensores de tráfico) con visibilidad en tiempo real limitada y análisis de causa raíz lento.",
      "s.cs1.so": "Streaming en tiempo real hacia capas Bronze · Silver · Gold, una base de conocimiento más capa semántica y un agente de datos para preguntas en lenguaje natural, sobre infraestructura de IA soberana con un LLM privado.",
      "s.cs1.o": "Tiempo hasta el insight: de semanas o meses a minutos, con analítica a escala de TB en segundos.",
      "s.cs2.tag": "Telecomunicaciones",
      "s.cs2.t": "De la información a la experiencia",
      "s.cs2.pr": "Conocimiento empresarial fragmentado entre ERP, CRM, SharePoint, sistemas documentales y herramientas de colaboración: no listo para IA, no gobernado y dependiente de unos pocos expertos.",
      "s.cs2.so": "Documentos no estructurados de S3, Google Drive y cargas de usuario analizados, fragmentados, vectorizados e indexados en una base de conocimiento gobernada, con respuestas que citan sus fuentes.",
      "s.cs2.o": "Encontrar información y obtener insights un 90 %+ más rápido, en soporte, operaciones, formación y ventas.",
      "s.cs3.tag": "Petróleo &amp; gas",
      "s.cs3.t": "De la adquisición de talento a la inteligencia de talento",
      "s.cs3.pr": "La contratación de alto volumen no escalaba: cribado manual de CV, evaluaciones inconsistentes y preocupación por enviar datos sensibles de RR. HH. a proveedores externos de IA, con un SLA de 50 000 CV al mes.",
      "s.cs3.so": "CV reconocidos, analizados y puntuados por LLM soberanos con soporte de árabe, puntuaciones escritas en tablas estructuradas y una interfaz sencilla para reclutadores con listas clasificadas, por suscripción o pago por uso.",
      "s.cs3.o": "Miles de currículos por hora, decenas de veces más rápido que el cribado manual. El mismo patrón aplica a facturas, contratos y licitaciones.",
      "s.ind7": "Energía &amp; servicios públicos",
