      "s.ind5": "Salud",
      "s.ind6": "Telecom y transporte",
      "p.hero.h": "Una plataforma Data + IA unificada y nativa de la nube",
      "p.hero.p": "Cuatro capas unificadas para cargas de IA, entregadas como dos productos (OmniFabric One y OmniFabric GenAI Workspace) gobernadas de extremo a extremo. Sus datos nunca salen de su dominio.",
      "p.hero.cta1": "Prueba gratis",
      "p.hero.cta2": "Ver la documentación",
      "p.ov.eb": "Por qué gana",
      "p.ov.h": "La respuesta a los cuatro problemas de datos",
      "p.ov.p": "Una plataforma · una copia de los datos · un solo stack. Datos multimodales, conocimiento, modelos y agentes sobre una única base, con un volante autooptimizado entre agente, datos y modelo.",
      "p.arch.eb": "Arquitectura &amp; tecnología central",
      "p.arch.h": "Cuatro capas unificadas, dos productos",
      "p.arch.p": "Los datos multimodales entran por abajo; las aplicaciones salen por arriba. Todo lo intermedio está gobernado de extremo a extremo y los datos nunca salen de su dominio.",
      "p.arch.src": "Fuentes de datos",
