      "p.eng.eb": "OmniFabric One",
      "p.eng.h": "El motor de datos unificado",
      "p.eng.p": "Cargas transaccionales, analíticas, de series temporales, vectoriales y de texto completo en una única base compatible con MySQL, con almacenamiento y cómputo ilimitados y escalables de forma independiente.",
      "p.eng1.s": "Motor todo en uno",
      "p.eng1.d": "Transaccional, analítico, series temporales, vectorial &amp; texto completo en una sola base de datos. Simplifique su arquitectura de datos.",
      "p.eng2.s": "Alta elasticidad",
      "p.eng2.d": "Almacenamiento y cómputo ilimitados, escalables de forma independiente.",
      "p.eng3.s": "Rentable",
      "p.eng3.d": "Pago por uso sobre almacenamiento compartido con una única fuente de datos.",
      "p.eng4.s": "Compatible con MySQL",
      "p.eng4.d": "Compatible en protocolo y SQL con MySQL 8.0: cero migración, herramientas conocidas.",
      "p.cm.eb": "OmniFabric GenAI Workspace",
      "p.cm.h": "De los datos brutos a los agentes de IA",
      "p.cm.p": "Un pipeline gobernado que convierte fuentes estructuradas y no estructuradas en conocimiento confiable y listo para IA, y luego lo sirve a agentes y búsqueda.",
      "p.cm1.t": "Fuentes de datos",
      "p.cm1.f1": "<b>SQL &amp; almacenamiento de objetos</b>: bases de datos, lagos y archivos, históricos e incrementales.",
      "p.cm1.f2": "<b>Documentos, medios &amp; SaaS</b>: PDF, imágenes, audio, vídeo y aplicaciones de negocio.",
      "p.cm2.t": "Integrar &amp; procesar",
      "p.cm2.f1": "<b>Limpieza, fragmentación &amp; enriquecimiento</b>: operadores integrados más nodos personalizados, orquestados visualmente.",
      "p.cm2.f2": "<b>Embedding &amp; versionado de datos</b>: cada base de conocimiento versionada, reproducible y reversible.",
      "p.cm3.t": "Modelos &amp; gobernanza",
      "p.cm3.f1": "<b>Orquestación de LLM, embedding, visión &amp; voz</b>: open source o comerciales, intercambiables.",
      "p.cm3.f2": "<b>RBAC &amp; privacidad</b>: acceso granular, protección de PII y linaje completo en cada llamada.",
      "p.cm4.t": "Servir",
      "p.cm4.f1": "<b>Agente de datos &amp; Chat2BI</b>: preguntas en lenguaje natural sobre todos sus datos, con agregación y detalle.",
      "p.cm4.f2": "<b>Búsqueda empresarial &amp; flujos agénticos</b>: respuestas fundamentadas con citas, y agentes que actúan.",
      "p.sec.eb": "Nivel empresarial",
      "p.sec.h": "Seguridad y control de acceso integrados",
      "p.sec1.t": "Control de acceso RBAC",
      "p.sec1.d": "Gestión granular de usuarios, roles, permisos y acceso a datos, hasta el nivel de columna.",
      "p.sec2.t": "Aislamiento multiinquilino",
      "p.sec2.d": "Inquilinos de espacio de trabajo aislados con almacenamiento y cómputo dedicados, para que equipos y datos nunca crucen fronteras.",
      "p.sec3.t": "Linaje y registros de auditoría",
      "p.sec3.d": "Cada transformación y decisión del agente es trazable de extremo a extremo: listo para auditorías de GDPR, SOC 2 y tus propias políticas.",
      "p.dep.eb": "Despliega a tu manera",
      "p.dep.h": "Despliegue privado o nube gestionada",
      "p.dep1.t": "Despliegue privado",
      "p.dep1.f1": "Entorno privado aislado: datos totalmente bajo tu control.",
      "p.dep1.f2": "Red privada de alto rendimiento, sin latencia de internet público.",
      "p.dep1.f3": "Despliegue único, uso prolongado, coste predecible.",
      "p.dep1.cta": "Contáctanos",
