      "nav.about": "Acerca de",
      "ab.eyebrow": "Acerca de OmniFabric",
      "ab.title": "Inteligencia de datos empresarial para la nube soberana",
      "ab.desc": "OmniFabric es una plataforma de inteligencia de datos de nivel empresarial: el Snowflake o Databricks de la nube soberana. Combina la nube soberana de CloudSigma con la plataforma de datos nativa de IA de MatrixOrigin, para que la IA funcione sobre datos confiables sin salir nunca de su jurisdicción.",
      "ab.mission.eyebrow": "Nuestra misión",
      "ab.mission.title": "Hacer de la IA confiable la norma — sobre una infraestructura que tú controlas",
      "ab.mission.p": "Toda organización debería poder ejecutar IA de producción sobre datos propios, con decisiones auditables. OmniFabric unifica todos sus datos, conocimiento e inteligencia en una infraestructura que usted controla por completo: del hype de la IA al ROI de la IA.",
      "ab.cs.tag": "Legado de nube",
      "ab.cs.name": "CloudSigma",
      "ab.cs.title": "Infraestructura de nube soberana y flexible",
      "ab.cs.p1": "Fundada en 2009 en Zúrich (Suiza) por Robert Jenkin y Patrick Baillie, CloudSigma fue pionera de un IaaS puro donde los clientes definen su propia infraestructura sin restricciones artificiales.",
      "ab.cs.p2": "Con operaciones en Zúrich, Las Vegas y Washington y más de 75 000 clientes, CloudSigma ofrece un Cloud-as-a-Service seguro, sostenible y soberano — y ahora también Intelligence-as-a-Service.",
      "ab.cs.f1l": "Fundada",
      "ab.cs.f1v": "2009",
      "ab.cs.f2l": "Sede",
      "ab.cs.f2v": "Zúrich, Suiza",
      "ab.cs.f3l": "Clientes",
      "ab.cs.f3v": "75 000+",
      "ab.cs.f4l": "Presencia",
      "ab.cs.f4v": "Zúrich · Las Vegas · Washington",
      "ab.cs.link": "Visitar cloudsigma.com",
      "ab.mo.tag": "Legado de datos e IA",
      "ab.mo.name": "MatrixOrigin",
      "ab.mo.title": "Una plataforma de inteligencia de datos AI-native",
      "ab.mo.p1": "Fundada en 2021 y respaldada por 5Y Capital y K2VC, MatrixOrigin desarrolla MatrixOne, una base de datos HTAP open source, nativa de IA y compatible con MySQL, con control de versiones Git-for-Data y búsqueda vectorial y de texto completo integrada.",
      "ab.mo.p2": "MatrixOne 1.0 llegó a GA en 2023, MatrixOne Intelligence se lanzó en 2024 y en 2025 la compañía se expandió globalmente con CloudSigma, con oficinas en EE. UU., Shanghái, Shenzhen y Pekín.",
      "ab.mo.f1l": "Fundada",
      "ab.mo.f1v": "2021",
      "ab.mo.f2l": "Oficinas",
      "ab.mo.f2v": "EE. UU. · Shanghái · Shenzhen · Pekín",
      "ab.mo.f3l": "Financiación",
      "ab.mo.f3v": "50 M$+ · 5Y Capital, K2VC",
      "ab.mo.f4l": "Motor",
      "ab.mo.f4v": "HTAP hiperconvergente · Git-for-Data",
      "ab.mo.link": "Visitar matrixorigin.io",
      "ab.together.eyebrow": "Por qué importa",
      "ab.together.title": "Dos bases, un tejido",
      "ab.together.p": "OmniFabric combina la nube soberana y flexible de CloudSigma con la plataforma de datos AI-native de MatrixOrigin — para datos e IA todo en uno sobre una infraestructura que controlas.",
      "ab.tg1.t": "Soberano por diseño",
      "ab.tg1.d": "Ejecuta en tu nube, on-premise o aislado — tus datos permanecen en tu región, bajo tu control.",
      "ab.tg2.t": "Todo en uno",
      "ab.tg2.d": "Datos, vectores, modelos y agentes en una sola plataforma, no una pila de servicios que ensamblar.",
      "ab.tg3.t": "Abierto y flexible",
      "ab.tg3.d": "Compatible con MySQL, SQL y APIs abiertas — define tu infraestructura a tu manera, sin bloqueo.",
      "ab.cta.title": "Descubre lo que un solo tejido puede hacer",
      "ab.cta.desc": "Explora la plataforma, o habla con nuestro equipo para unir datos soberanos e IA.",
      "ab.cta.b1": "Explorar la plataforma",
      "ab.cta.b2": "Contáctanos",
