      "hero.badge.pill": "NUEVO",
      "hero.badge.text": "El runtime de agentes y la memoria de largo plazo ya están en disponibilidad general",
      "hero.title": "Inteligencia de datos empresarial<br><span class=\"grad\">para la nube soberana.</span>",
      "hero.lead": "OmniFabric unifica todos los datos, el conocimiento y la inteligencia de su empresa en una infraestructura que usted controla por completo, para que la IA funcione sobre datos confiables sin salir nunca de su jurisdicción.",
      "hero.cta1": "Empezar gratis",
      "hero.cta2": "Explorar la plataforma",
      "hero.trust": "Con la confianza de empresas de todos los sectores y regiones",
      "fw.sub": "Autooptimizado",
      "fw.title": "Volante",
      "node.agent": "Agente",
      "node.model": "Modelo",
      "node.data": "Datos",
      "hero.float1": "Una sola copia de los datos",
      "hero.float2": "Cada decisión es trazable",
      "logos.title": "Con la confianza de empresas de todos los sectores &amp; regiones",
      "pillars.eyebrow": "Conozca OmniFabric",
      "pillars.title": "Una plataforma · una copia de los datos · un solo stack",
      "pillars.desc": "Una plataforma Data + IA unificada y nativa de la nube. El cerebro, la memoria y las manos de la IA empresarial (modelo, datos y agentes) sobre una única base gobernada, reforzándose en un volante autooptimizado.",
      "pillar1.tag": "La memoria · Datos",
      "pillar1.title": "Su conocimiento empresarial privado",
      "pillar1.desc": "Una sola copia de datos estructurados, semiestructurados y no estructurados (registros ERP, contratos, registros de cadena de suministro, correos) gobernada con linaje completo. Esto es lo que hace que la IA entienda de verdad su negocio.",
      "pillar2.tag": "El cerebro · Modelo",
      "pillar2.title": "Cualquier modelo, totalmente gobernado",
      "pillar2.desc": "Servicio unificado de modelos de lenguaje, embedding, reranking, visión y voz (open source o comerciales, sin bloqueo) con cada llamada trazable.",
      "pillar3.tag": "Las manos · Agentes",
      "pillar3.title": "Agentes que actúan y mejoran",
      "pillar3.desc": "Cree, orqueste, evalúe y ejecute agentes que interactúan con ERP, CRM y API, sobre un runtime auditable con memoria a largo plazo que mejora en producción.",
      "stat1.lbl": "Entrega de agentes más rápida: semanas, no meses",
      "stat2.lbl": "Menor TCO: sin sistemas redundantes ni copias de datos",
      "stat3.lbl": "Auditabilidad: cada decisión de IA rastreada hasta sus datos",
      "stat4.lbl": "Para empezar: pago por uso, sin licencia, sin mínimo",
      "cap.eyebrow": "Capacidades de la plataforma",
      "cap.title": "Una plataforma de datos diseñada para la era de los agentes",
      "cap.desc": "Todo lo necesario para llevar tus aplicaciones de IA del prototipo a producción — sin integrar tú mismo media docena de sistemas.",
      "cap1.eyebrow": "OmniFabric Core · Plataforma de datos",
      "cap1.title": "Una base hiperconvergida y cloud-native",
      "cap1.desc": "Un único motor para cargas transaccionales y analíticas, con almacenamiento y cómputo desacoplados para escalar de forma independiente y bajo demanda.",
      "cap1.li1": "<b>HTAP en un solo motor</b> — sirve OLTP y OLAP desde los mismos datos, sin pipelines que sincronizar.",
      "cap1.li2": "<b>Almacenamiento y cómputo desacoplados</b> — escala el rendimiento de consultas y la capacidad por separado.",
      "cap1.li3": "<b>Búsqueda vectorial y ML integrados</b> — embeddings e inferencia junto a tus datos.",
      "cap1.li4": "<b>Clonado sin copia y time travel</b> — ramifica y revierte conjuntos de datos al instante.",
      "cap1.link": "Explorar OmniFabric Core",
      "cap2.eyebrow": "OmniFabric Intelligence · Multimodal",
      "cap2.title": "Convierte cualquier dato en contexto listo para IA",
      "cap2.desc": "Ingiere fuentes estructuradas, semiestructuradas y no estructuradas, y luego analízalas, extrae y enlázalas en una base de conocimiento que se actualiza continuamente.",
      "cap2.li1": "<b>Ingesta unificada</b> — bases de datos, archivos, APIs y streams en una sola plataforma.",
