      "rl.q": "ChatGPT لا يعرف عملك.",
      "rl.qp": "الذكاء الاصطناعي العام بارع لكنه يفتقر إلى سياقك الخاص. بدون بياناتك، يبقى الذكاء الاصطناعي مجرد غريب عالي الذكاء في مكتبك.",
      "rl.k1": "سجلات المعاملات الداخلية في SAP / ERP",
      "rl.k2": "البيانات القانونية وبيانات الامتثال الخاصة",
