      "rl.k4": "البريد الإلكتروني ومحادثات المبيعات غير المهيكلة",
      "rl.four.h": "أربع حقائق في البيانات تمنع الذكاء الاصطناعي من الوصول إلى الإنتاج على نطاق واسع",
      "rl.d1.t": "جزر البيانات",
      "rl.d1.d": "تشغّل المؤسسات 10–50+ وكيلًا بالتوازي. نقل البيانات بين الأنظمة المجزّأة هو عنق الزجاجة الرئيسي — والسياق المنفصل ينتج نتائج ذكاء اصطناعي سيئة.",
