      "s.cs3.so": "سير ذاتية تُتعرَّف وتُحلَّل وتُقيَّم بنماذج لغوية سيادية تدعم العربية، ودرجات تُكتب في جداول مهيكلة، وواجهة بسيطة لمسؤولي التوظيف بقوائم مرتّبة — بالاشتراك أو الدفع حسب الاستخدام.",
