      "px.cn.h": "اشترِ الحوسبة بالساعة أو بالشهر",
      "px.cn.p": "حوسبة تُباع بالعقدة تُشغّل المنصة بأكملها — البيانات والنماذج والوكلاء. استوعب الذروات بالدفع حسب الاستخدام، أو احجز عُقدًا شهرية ووفّر.",
      "px.cn.note": "تُحتسب العُقد بالساعة بالثانية وبلا التزام — مثالية للذروات والمهام الدفعية والتطوير. أما العُقد الشهرية فهي حجز ثابت وأرخص بنحو 20%. التخزين والبيانات منفصلان عن الحوسبة، فيمكنك توسيع العُقد أو تقليصها في أي وقت دون فقدان الحالة.",
      "px.cn.cta": "ابدأ الآن",
