      "px.ai.t": "خدمات الذكاء الاصطناعي",
      "px.ai.p": "اتصل بأكثر من 100 نموذج مُستضاف — محادثة وتضمينات وإعادة ترتيب — عبر واجهة برمجة واحدة. يُحتسب لكل مليون رمز (token)؛ استخدم مفاتيح مزوّدك الخاصة للتمرير بسعر التكلفة.",
