      "px.eg.free": "أول 100 غيغابايت شهريًا مجانًا",
      "px.from": "ابتداءً من",
      "px.inc": "<b>كل عقدة تأتي بمنصة الوكيل · النموذج · البيانات كاملةً</b> — بحث متجهي أصلي، واستعلامات HTAP، وحوكمة، وتتبّع المنشأ، وتسجيل دخول موحّد (SSO). لا شيء محجوب خلف باقة أعلى، وكل استخدام يُقاس في سجلات قابلة للتدقيق.",
      "px.usd": "جميع الأسعار بالدولار الأمريكي وبدون الضرائب المحلية. يُحتسب الاستخدام بالساعة بالثانية؛ والعُقد الشهرية حجز ثابت.",
      "px.faq.eb": "الأسئلة الشائعة",
      "px.faq.h": "أسئلة التسعير، بإجابات واضحة",
      "px.faq.q1": "شهري أم بالساعة — أيهما أختار؟",
      "px.faq.a1": "استخدم الدفع بالساعة حسب الاستخدام للأحمال المتذبذبة أو القصيرة أو التجريبية — يُحتسب بالثانية وبلا التزام. واحجز عُقدًا شهرية للإنتاج المستقر ووفّر نحو 20%. يمكنك المزج بينهما في المشروع نفسه وتبديل العقدة بين الوضعين في أي وقت.",
      "px.faq.q2": "كيف تُحتسب رموز الذكاء الاصطناعي؟",
      "px.faq.a2": "كل استدعاء للنموذج يُقاس برموز الإدخال والإخراج ويُسعّر لكل مليون. استخدم النماذج الموجّهة من OmniFabric أو مفاتيح مزوّدك الخاصة — وفي هذه الحالة تُمرَّر الرموز بسعر تكلفة المزوّد دون هامش، مع بقائها ضمن التتبّع والحوكمة ذاتها.",
      "px.faq.q3": "هل يتغيّر السعر حسب المنطقة؟",
      "px.faq.a3": "أسعار القائمة موحّدة في المناطق السبع جميعها. تُعالَج بياناتك وتُخزَّن فقط في المنطقة التي تختارها. للاستخدام الملتزم أو الكبير في منطقة بعينها، تواصل مع المبيعات للحصول على عرض مخصّص.",
      "px.faq.q4": "هل هناك طريقة مجانية للبدء؟",
      "px.faq.a4": "نعم — أنشئ مساحة عمل مجانًا، واربط مصدرًا، وأطلق أول وكيل. لا تبدأ الدفع إلا عند تجهيز عقدة حوسبة أو استهلاك خدمات ذكاء اصطناعي أو تخزين أو حركة صادرة مُقاسة.",
      "px.faq.q5": "ما الذي يُعدّ تخزينًا وحركة صادرة؟",
      "px.faq.a5": "التخزين هو البيانات التي تحتفظ بها في المنصة — جداول ومتجهات وملفات — وتُحتسب لكل غيغابايت-شهر. والحركة الصادرة هي ما يغادر المنطقة إلى الإنترنت العام. أما قراءة بياناتك الخاصة والحركة داخل المنطقة فمجانية.",
      "px.cta.h": "ابدأ مجانًا، ووسّع عندما تكون جاهزًا",
      "px.cta.p": "شغّل مساحة عمل، وجهّز أول عقدة بالساعة، ولا تلتزم شهريًا إلا عند الوصول إلى الإنتاج.",
      "px.cta.b1": "ابدأ البناء مجانًا",
      "px.cta.b2": "تواصل مع المبيعات",
