      "demo.cta.d": "ابدأ مجانًا واربط مصدرك الأول في دقائق، أو احجز عرضًا مباشرًا مع فريقنا.",
      "sov.h.eb": "سيادة البيانات",
      "sov.h.h": "بياناتك وذكاؤك الاصطناعي لا يغادران سيطرتك أبدًا",
      "sov.h.p": "للأحمال الخاضعة للتنظيم والحرجة، تعمل OmniFabric حيث يجب أن تقيم بياناتك — منطقتك وبنيتك التحتية وقواعدك. إقامة كاملة للبيانات ومرونة في النشر وحوكمة شاملة، مدمجة.",
      "sov.h.c1t": "إقامة البيانات الإقليمية",
      "sov.h.c1d": "تبقى بياناتك ونماذجك داخل المنطقة افتراضيًا، بما يلبّي متطلبات إقامة البيانات والسيادة المحلية.",
      "sov.h.c2t": "انشر في أي مكان",
      "sov.h.c2d": "شغّلها على سحابة محلية أو داخل مؤسستك أو على الحافة الهجينة — المنصة نفسها، حيثما يتطلّب الامتثال.",
      "sov.h.c3t": "حوكمة موحّدة",
      "sov.h.c3d": "تحكّم بالوصول (RBAC) وسجلّات تدقيق كاملة ولقطات لكل نتيجة يقودها الذكاء الاصطناعي — دون قرارات صندوق أسود.",
      "sov.h.c4t": "جاهز للامتثال",
      "sov.h.c4d": "احمِ البيانات الشخصية، وتتبّع كل قرار من البداية إلى النهاية، وأعد إنتاج أي نتيجة للموافقة القانونية والتنظيمية.",
      "sov.p.h": "سيادي بالتصميم — انشر في أي مكان، وتحكّم في كل شيء",
      "sov.p.p": "يتطلّب الذكاء الاصطناعي الحرج سيادة وحوكمة صارمة. تُبقي OmniFabric بياناتك في منطقتك وعلى بنية تحتية تتحكّم بها، مع قابلية تدقيق كاملة لكل استدعاء نموذج وقرار وكيل.",
      "sov.p.m1t": "سحابة محلية",
      "sov.p.m1d": "انشر في منطقة سيادية من السحابة التي تختارها — لا تتجاوز بياناتك الحدود أبدًا.",
      "sov.p.m2t": "داخل المؤسسة",
