      "cc1.ch": "كانت ميزات ونماذج الذكاء الاصطناعي يُعاد بناؤها في صوامع بين الأقسام، ما أبطأ كل مشروع وضخّم تكاليف الحوسبة.",
      "cc1.sol": "بنت Tencent على OmniFabric منصة بيانات متعددة الوسائط ونظامًا لإدارة الميزات، لتنشر الفرق الميزات وتكتشفها وتعيد استخدامها من مخزن محوكم واحد.",
