      "cc3.ch": "كان إطلاق كل منتج جديد يعني شهرًا أو شهرين من التواصل المتكرر وجلسات التدريب الجماعي قبل أن يصبح موظفو التسويق جاهزين لترويجه.",
      "cc3.sol": "وحّد OmniFabric مواد الحالات الداخلية ووثائق المنتجات في مساعد تدريب بالذكاء الاصطناعي، ليتعلّم موظفو التسويق ويتدرّبوا ذاتيًا على ترويج المنتجات الجديدة.",
      "cc3.res": "ارتفعت كفاءة التدريب بنسبة 80%: يتأهّل الموظفون على المنتجات الجديدة بأنفسهم، مع توجيه خفيف من مديري القنوات بدل أشهر من اجتماعات التدريب المتكررة.",
      "cc4.ch": "كان إعداد كل حزمة عطاء يستغرق أسبوعًا أو أسبوعين من التجميع اليدوي، بجمع المواد المتناثرة والحالات السابقة يدويًا.",
      "cc4.sol": "دمج OmniFabric مواد العطاءات الداخلية والحالات التاريخية في وكيل عطاءات يصوغ حزم العروض تلقائيًا.",
      "cc4.res": "انخفض زمن إعداد حزمة العطاء من أسبوع أو أسبوعين إلى يوم أو يومين — أي أسرع بنحو 10 أضعاف.",
      "cc5.ch": "كان المحلّلون يقضون معظم وقتهم في جمع البيانات من أكثر من 60 مصدرًا بدل تكوين رؤية.",
      "cc5.sol": "نشرت Stone Castle منصة OmniFabric لأتمتة الأبحاث عبر أكثر من 60 مصدرًا مع مراقبة المحفظة في الوقت الفعلي.",
      "cc5.res": "تحرّر نحو 80% من وقت المحللين للتركيز على الاستراتيجية، مع مراقبة فورية.",
      "cc6.ch": "كانت مراجعة المطالبات والوثائق يدويًا بطيئة، ويسهل تفويت بنود المخاطر تحت ضغط المواعيد.",
      "cc6.sol": "حوّل ذكاء المستندات على OmniFabric المطالبات والوثائق إلى قاعدة معرفة ذاتية التحديث، مع مخاطر مكتشفة بالذكاء الاصطناعي ومُسندة.",
      "cc6.res": "انخفضت مراجعة بنود المخاطر من 16 يومًا إلى نحو دقيقة واحدة.",
      "s.hero.eb": "الحلول",
      "s.hero.h": "حوّل بيانات مؤسستك إلى أصول جاهزة للذكاء الاصطناعي",
      "s.hero.p": "كل نمط عالي القيمة هو خط أنابيب محكوم واحد على OmniFabric — من البيانات الخام إلى نتيجة في الإنتاج. من قدرات البيانات إلى الوكلاء المنشورين، منصة واحدة تشغّل كل شيء.",
      "s.cap.eb": "قدرات بيانات الذكاء الاصطناعي",
      "s.cap.h": "ابنِ الأساس الذي يعمل عليه ذكاؤك الاصطناعي",
      "s.cap.p": "خمس قدرات أساسية تحوّل بيانات المؤسسة الخام والمجزّأة إلى أصول موثوقة وجاهزة للذكاء الاصطناعي.",
      "s.c1.t": "ذكاء المستندات",
      "s.c1.d": "حرّر البيانات المحتجزة في المستندات المعقّدة. أتمتة المسار بالكامل — التحليل والاستخراج والتوليد — وابنِ Document Copilot جاهزًا للإنتاج.",
      "s.c1.f1": "تحليل واستخراج ذكي للمستندات",
      "s.c1.f2": "فهم دلالي متعدد الوسائط",
      "s.c1.f3": "قاعدة معرفة بمستوى المؤسسات",
      "s.c2.t": "Agentic RAG",
      "s.c2.d": "امنح الوكلاء ما يتجاوز البحث. تمنح المعالجة متعددة الوسائط القوية لـ Agentic RAG أساسًا متينًا للاستدلال المتقدّم والتنفيذ الدقيق.",
      "s.c2.f1": "تكامل غير متجانس متعدد المصادر",
      "s.c2.f2": "بناء قاعدة معرفة متعددة الوسائط",
      "s.c2.f3": "دعم واستجابة بيانات سلسة",
      "s.c3.t": "ضبط نماذج LLM",
      "s.c3.d": "حوّل بياناتك الخاصة إلى ميزة تنافسية. عالج البيانات الخام ونظّمها في مجموعات تدريب عالية الجودة ليصبح نموذجك خبيرًا حقيقيًا في المجال.",
      "s.c3.f1": "تحليل ذكاء اصطناعي متعدد الوسائط",
      "s.c3.f2": "معالجة بيانات منخفضة الكود",
      "s.c3.f3": "توليد بيانات تدريب عالية الجودة",
      "s.c4.t": "ETL للبيانات متعددة الوسائط",
      "s.c4.d": "عالج تجزّؤ البيانات في عصر الذكاء الاصطناعي. ادمج مصادر متنوّعة ومجزّأة عبر موصّلات متقدّمة في مسارات عالية الجودة جاهزة للوكلاء.",
      "s.c4.f1": "موصّلات غير متجانسة متعددة المصادر",
      "s.c4.f2": "مراقبة المسار من البداية إلى النهاية",
      "s.c4.f3": "جدولة مهام مرنة",
      "s.c5.t": "أساس بيانات الذكاء الاصطناعي",
      "s.c5.d": "توسّع بسهولة في عصر الوكلاء. أساس موحّد وعالي الأداء مصمّم لإنتاجية وسرعة أحمال الذكاء الاصطناعي الحديثة.",
      "s.c5.f1": "تحليلات بيانات بحجم بيتابايت",
      "s.c5.f2": "إدارة بيانات متعددة الوسائط",
      "s.c5.f3": "قابلية توسّع مرنة متعددة السحابات",
      "s.ag.eb": "تطبيقات وكلاء الذكاء الاصطناعي",
      "s.ag.h": "وكلاء إنتاج لسير العمل عالي القيمة",
      "s.ag.p": "تطبيقات وكلاء جاهزة تُفعّل أساس بيانات الذكاء الاصطناعي لديك.",
      "s.a1.t": "مراجعة العقود",
