      "p.hero.p": "أربع طبقات موحّدة لأحمال الذكاء الاصطناعي، تُقدَّم كمنتجين — OmniFabric One وOmniFabric GenAI Workspace — بحوكمة من طرف إلى طرف. بياناتك لا تغادر نطاقك أبدًا.",
