      "ab.eyebrow": "عن OmniFabric",
      "ab.title": "ذكاء بيانات المؤسسات للسحابة السيادية",
      "ab.desc": "OmniFabric منصة ذكاء بيانات بمستوى المؤسسات — بمثابة Snowflake أو Databricks للسحابة السيادية. تجمع بين السحابة السيادية من CloudSigma ومنصة البيانات الأصيلة للذكاء الاصطناعي من MatrixOrigin، لتعمل الذكاء الاصطناعي على بيانات موثوقة دون أن تغادر نطاق ولايتك القانونية أبدًا.",
      "ab.mission.eyebrow": "مهمتنا",
      "ab.mission.title": "جعل الذكاء الاصطناعي الموثوق هو الأصل — على بنية تحت سيطرتك",
      "ab.mission.p": "ينبغي لكل مؤسسة أن تتمكن من تشغيل ذكاء اصطناعي إنتاجي على بيانات تملكها، بقرارات يمكن تدقيقها. يوحّد OmniFabric جميع بيانات مؤسستك ومعرفتها وذكائها على بنية تحتية تتحكم بها بالكامل — من ضجيج الذكاء الاصطناعي إلى عائد الاستثمار منه.",
      "ab.cs.tag": "إرث سحابي",
      "ab.cs.name": "CloudSigma",
      "ab.cs.title": "بنية سحابية سيادية ومرنة",
      "ab.cs.p1": "تأسّست CloudSigma عام 2009 في زيورخ بسويسرا على يد Robert Jenkin وPatrick Baillie، وكانت رائدة في تقديم IaaS نقيّ يحدّد فيه العملاء بنيتهم التحتية دون قيود مصطنعة.",
      "ab.cs.p2": "تعمل من زيورخ ولاس فيغاس وواشنطن وتخدم أكثر من 75,000 عميل، وتقدّم Cloud-as-a-Service آمنًا ومستدامًا وسياديًا — والآن Intelligence-as-a-Service.",
      "ab.cs.f1l": "التأسيس",
      "ab.cs.f1v": "2009",
      "ab.cs.f2l": "المقر",
      "ab.cs.f2v": "زيورخ، سويسرا",
      "ab.cs.f3l": "العملاء",
      "ab.cs.f3v": "+75,000",
      "ab.cs.f4l": "الانتشار",
      "ab.cs.f4v": "زيورخ · لاس فيغاس · واشنطن",
      "ab.cs.link": "زيارة cloudsigma.com",
      "ab.mo.tag": "إرث البيانات والذكاء الاصطناعي",
      "ab.mo.name": "MatrixOrigin",
      "ab.mo.title": "منصة ذكاء بيانات أصيلة للذكاء الاصطناعي",
      "ab.mo.p1": "تأسست MatrixOrigin عام 2021 بدعم من 5Y Capital وK2VC، وتبني MatrixOne — قاعدة بيانات HTAP مفتوحة المصدر وأصيلة للذكاء الاصطناعي ومتوافقة مع MySQL، مع تحكم بالإصدارات Git-for-Data وبحث متجهي ونصي كامل مدمج.",
      "ab.mo.p2": "أصبح MatrixOne 1.0 متاحًا عمومًا عام 2023، وأُطلق MatrixOne Intelligence عام 2024، وفي 2025 توسّعت الشركة عالميًا مع CloudSigma — بمكاتب في الولايات المتحدة وشنغهاي وشنجن وبكين.",
      "ab.mo.f1l": "التأسيس",
      "ab.mo.f1v": "2021",
      "ab.mo.f2l": "المكاتب",
      "ab.mo.f2v": "الولايات المتحدة · شنغهاي · شنجن · بكين",
      "ab.mo.f3l": "التمويل",
      "ab.mo.f3v": "أكثر من 50 مليون دولار · 5Y Capital وK2VC",
      "ab.mo.f4l": "المحرّك",
      "ab.mo.f4v": "HTAP فائق التقارب · Git-for-Data",
      "ab.mo.link": "زيارة matrixorigin.io",
      "ab.together.eyebrow": "لماذا يهمّ ذلك",
      "ab.together.title": "أساسان، ونسيج واحد",
      "ab.together.p": "يجمع OmniFabric بين سحابة CloudSigma السيادية المرنة ومنصة بيانات MatrixOrigin الأصيلة للذكاء الاصطناعي — ليمنحك بيانات وذكاءً اصطناعيًا متكاملين على بنية تحت سيطرتك.",
      "ab.tg1.t": "سياديّ بالتصميم",
      "ab.tg1.d": "شغّله في سحابتك أو محليًا أو في بيئة معزولة — تبقى بياناتك في منطقتك وتحت سيطرتك.",
      "ab.tg2.t": "الكل في واحد",
      "ab.tg2.d": "البيانات والمتجهات والنماذج والوكلاء في منصة واحدة، لا منظومة خدمات يجب تجميعها.",
      "ab.tg3.t": "مفتوح ومرن",
      "ab.tg3.d": "متوافق مع MySQL وSQL وواجهات API مفتوحة — عرّف بنيتك بطريقتك، دون تقييد.",
      "ab.cta.title": "اكتشف ما يستطيعه نسيج واحد",
      "ab.cta.desc": "استكشف المنصة، أو تحدّث إلى فريقنا حول الجمع بين البيانات السيادية والذكاء الاصطناعي.",
      "ab.cta.b1": "استكشف المنصة",
      "ab.cta.b2": "تواصل معنا",
