      "prod.eyebrow": "المنصة",
      "prod.title": "نسيج واحد فائق التقارب للبيانات والنماذج والوكلاء",
      "prod.desc": "كل ما يجمعه OmniFabric — أساس بيانات سحابي أصلي، وذكاء متعدد الوسائط، وبيئة تشغيل وكلاء موثوقة، وذاكرة طويلة الأمد، ومناطق سيادية تتحكم بها.",
      "nav.capabilities": "القدرات",
