      "s.cs1.t": "Dari kekacauan data ke wawasan bisnis",
      "s.cs1.pr": "Data operasional terfragmentasi di sistem OT dan IT — gerbang tol, ANPR, RFID, gateway pembayaran, sensor lalu lintas — dengan visibilitas waktu nyata yang terbatas dan analisis akar masalah yang lambat.",
      "s.cs1.so": "Streaming waktu nyata ke lapisan Bronze · Silver · Gold, basis pengetahuan plus lapisan semantik, dan agen data untuk tanya jawab bahasa alami — di infrastruktur AI berdaulat dengan LLM privat.",
      "s.cs1.o": "Waktu menuju wawasan: dari berminggu-minggu atau berbulan-bulan menjadi hitungan menit, dengan analitik skala TB dalam hitungan detik.",
      "s.cs2.tag": "Telekomunikasi",
      "s.cs2.t": "Dari informasi ke keahlian",
      "s.cs2.pr": "Pengetahuan perusahaan terfragmentasi di ERP, CRM, SharePoint, sistem dokumen, dan alat kolaborasi — belum siap AI, belum terkelola, dan bergantung pada segelintir pakar.",
      "s.cs2.so": "Dokumen tidak terstruktur dari S3, Google Drive, dan unggahan pengguna diurai, dipotong, divektorisasi, dan diindeks ke basis pengetahuan terkelola, dengan jawaban yang menyertakan sitasi sumber.",
      "s.cs2.o": "Menemukan informasi dan memunculkan wawasan 90%+ lebih cepat — di dukungan, operasi, pelatihan, dan penjualan.",
      "s.cs3.tag": "Minyak &amp; gas",
      "s.cs3.t": "Dari akuisisi talenta ke kecerdasan talenta",
      "s.cs3.pr": "Rekrutmen bervolume tinggi tidak dapat diskalakan: penyaringan CV manual, penilaian yang tidak konsisten, dan kekhawatiran mengirim data SDM sensitif ke penyedia AI eksternal — dengan SLA 50.000 CV per bulan.",
      "s.cs3.so": "CV dikenali, diurai, dan dinilai oleh LLM berdaulat dengan dukungan bahasa Arab, skor ditulis ke tabel terstruktur, dan antarmuka perekrut yang sederhana untuk daftar pendek berperingkat — berlangganan atau bayar sesuai pemakaian.",
      "s.cs3.o": "Ribuan CV per jam — puluhan kali lebih cepat dari penyaringan manual. Pola yang sama berlaku untuk faktur, kontrak, dan tender.",
