      "p.l3.t": "Lapisan Basis Data &amp; Layanan AI",
      "p.l3.i1": "Penyimpanan hyper-konvergen multi-model",
      "p.l3.i2": "HTAP · vektor · pencarian teks lengkap",
      "p.l3.i3": "Model LLM &amp; embedding",
      "p.l3.i4": "Model visi &amp; ucapan",
      "p.arch.out": "Output yang siap-AI",
      "p.out1": "Agen Pencarian Cerdas",
      "p.out2": "Aplikasi Dokumen Cerdas",
