      "p.out4": "Pelatihan Model AI",
      "p.eng.eb": "OmniFabric One",
      "p.eng.h": "Mesin data terpadu",
      "p.eng.p": "Beban kerja transaksional, analitik, deret waktu, vektor, dan teks penuh dalam satu basis data yang kompatibel dengan MySQL — dengan storage dan komputasi tanpa batas yang dapat diskalakan secara independen.",
      "p.eng1.s": "Mesin serba ada",
      "p.eng1.d": "Transaksional, analitik, deret waktu, vektor &amp; teks penuh — dalam satu basis data. Sederhanakan arsitektur data Anda.",
      "p.eng2.s": "Elastisitas tinggi",
      "p.eng2.d": "Storage dan komputasi tanpa batas, dapat diskalakan secara independen.",
      "p.eng3.s": "Hemat biaya",
      "p.eng3.d": "Bayar sesuai pemakaian di storage bersama dengan satu sumber data.",
      "p.eng4.s": "Kompatibel MySQL",
      "p.eng4.d": "Kompatibel protokol dan SQL dengan MySQL 8.0 — tanpa migrasi, dengan alat yang sudah dikenal.",
      "p.cm.eb": "OmniFabric GenAI Workspace",
      "p.cm.h": "Dari data mentah ke agen AI",
      "p.cm.p": "Pipeline terkelola yang mengubah sumber terstruktur dan tidak terstruktur menjadi pengetahuan tepercaya yang siap AI — lalu menyajikannya ke agen dan pencarian.",
      "p.cm1.t": "Sumber data",
      "p.cm1.f1": "<b>SQL &amp; object storage</b> — basis data, data lake, dan file, historis maupun inkremental.",
      "p.cm1.f2": "<b>Dokumen, media &amp; SaaS</b> — PDF, gambar, audio, video, dan aplikasi bisnis.",
      "p.cm2.t": "Integrasi &amp; proses",
      "p.cm2.f1": "<b>Pembersihan, pemotongan &amp; pengayaan</b> — operator bawaan plus node kustom, diorkestrasi secara visual.",
      "p.cm2.f2": "<b>Embedding &amp; versioning data</b> — setiap basis pengetahuan berversi, dapat direproduksi, dan dapat di-rollback.",
      "p.cm3.t": "Model &amp; tata kelola",
      "p.cm3.f1": "<b>Orkestrasi LLM, embedding, visi &amp; suara</b> — open source atau komersial, dapat diganti.",
      "p.cm3.f2": "<b>RBAC &amp; privasi</b> — akses granular, perlindungan PII, dan lineage lengkap di setiap panggilan.",
      "p.cm4.t": "Sajikan",
      "p.cm4.f1": "<b>Agen data &amp; Chat2BI</b> — pertanyaan bahasa alami atas seluruh data Anda, dengan agregasi dan drill-down.",
      "p.cm4.f2": "<b>Pencarian enterprise &amp; alur kerja agentik</b> — jawaban berbasis sumber dengan sitasi, dan agen yang bertindak.",
      "p.sec.eb": "Kelas enterprise",
      "p.sec.h": "Keamanan &amp; kontrol akses, sudah terpasang",
      "p.sec1.t": "Kontrol akses RBAC",
      "p.sec1.d": "Manajemen granular atas pengguna, peran, izin fitur, dan akses data — hingga ke tingkat kolom.",
      "p.sec2.t": "Isolasi multi-tenant",
      "p.sec2.d": "Tenant ruang kerja terisolasi dengan penyimpanan dan komputasi khusus, sehingga tim dan data tak pernah saling bocor antar batas.",
      "p.sec3.t": "Silsilah &amp; jejak audit",
      "p.sec3.d": "Setiap transformasi dan keputusan agen dapat ditelusuri menyeluruh — siap audit untuk GDPR, SOC 2, dan kebijakan Anda sendiri.",
