      "rg.cta.title": "Butuh wilayah yang belum kami daftarkan?",
      "rg.cta.desc": "Kami menerapkan wilayah berdaulat sesuai permintaan, termasuk on-prem dan air-gapped. Beri tahu kami di mana Anda butuh OmniFabric.",
      "rg.cta.b1": "Minta wilayah",
