      "cust.eyebrow": "Studi kasus",
      "cust.title": "Bagaimana tim membangun di atas OmniFabric",
      "cust.desc": "Penerapan nyata di berbagai industri — tantangan, solusi, dan hasil yang terukur.",
      "cust.challenge": "Tantangan",
      "cust.solution": "Solusi",
