      "cust.cta.title": "Jadilah kisah sukses berikutnya",
      "cust.cta.desc": "Mulai gratis, atau bicarakan kasus penggunaan Anda dengan tim kami.",
      "case1.tag": "Teknologi",
      "case1.sub": "penggunaan ulang fitur",
      "case1.title": "Platform data &amp; fitur multimodal terpadu",
      "case1.desc": "Tim berhenti membangun ulang model yang sama — penggunaan ulang fitur antar-departemen naik 40% dan siklus pengembangan menyusut 30%.",
      "case1.who": "Tim platform AI",
      "case2.tag": "Ritel SaaS",
      "case2.sub": "wawasan lebih cepat",
      "case2.title": "Analitik real-time untuk setiap merchant",
      "case2.desc": "Data transaksi bervolume tinggi dianalisis real-time — wawasan dan copilot merchant yang instan.",
      "case2.who": "Platform POS ritel",
      "case3.tag": "Ritel · Penjualan langsung",
      "case3.sub": "efisiensi pelatihan lebih tinggi",
      "case3.title": "Asisten pelatihan AI untuk peluncuran produk baru",
      "case3.desc": "Materi kasus internal dan dokumentasi produk disatukan dalam asisten AI — staf pemasaran belajar mandiri cara mempromosikan produk baru, bukan pelatihan kelompok berbulan-bulan.",
      "case3.who": "Amway Nutrilite",
      "case4.tag": "Manufaktur",
      "case4.sub": "produksi tender lebih cepat",
      "case4.title": "Agen tender yang menyusun draf paket proposal",
      "case4.desc": "Materi tender dan kasus historis menggerakkan agen yang menyusun paket tender dalam 1–2 hari, bukan 1–2 minggu.",
      "case4.who": "JST Power Equipment",
      "case5.tag": "Keuangan",
      "case5.sub": "waktu analis dibebaskan",
      "case5.title": "Riset investasi otomatis berskala besar",
      "case5.desc": "Riset otomatis di 60+ sumber data membebaskan sekitar 80% waktu analis untuk strategi.",
      "case5.who": "Firma investasi",
      "case6.tag": "Asuransi",
      "case6.sub": "tinjauan klaim",
      "case6.title": "Tinjauan risiko klaim &amp; polis instan",
      "case6.desc": "Tinjauan klausul risiko turun dari 16 hari menjadi sekitar satu menit, dan basis pengetahuan selalu mutakhir.",
      "case6.who": "Perusahaan asuransi",
      "tst.eyebrow": "Kisah pelanggan",
      "tst.title": "Tim merilis lebih cepat saat satu fabric menopang setiap keputusan",
      "tst1.q": "Kami memensiunkan basis data vektor dan pekerjaan ETL terpisah. Pencarian, analitik, dan agen kami kini membaca data langsung yang sama — tanpa salinan basi dan tanpa sistem tambahan untuk dikelola.",
      "tst1.role": "Tim platform AI",
      "tst2.q": "Silsilah keputusan adalah kuncinya. Setiap tindakan agen dapat dijelaskan dan dibalik, sehingga kepatuhan menyetujui dan kami masuk produksi dalam hitungan minggu, bukan kuartal.",
      "tst2.role": "Firma investasi",
      "tst3.q": "Tinjauan kontrak turun dari lebih dari dua minggu menjadi sekitar satu menit. Basis pengetahuan memperbarui dirinya, sehingga analis kami fokus pada penilaian, bukan entri data.",
      "tst3.role": "Perusahaan asuransi",
